(*--------------------------------------------------------------*)
(* Model:    Scalar Leptoquark S1 add-on to SM                  *)
(* Purpose:  QCD pair production + Yukawa decay S -> e u        *)
(* Notes:    Keeps full QCD and (optionally) hypercharge.       *)
(*           Yukawa written phenomenologically (first gen).     *)
(*           Good for MG5: pp > S1 S1~ , S1 > e- u , etc.       *)
(*--------------------------------------------------------------*)

M$ModelName = "S1_LQ_RR";
(*First-generation-philic Scalar leptoquark S1 ~ (3, 1, -1/3)*)

(* ************************** *)
(* *****  Information   ***** *)
(* ************************** *)

M$Information = {
  Authors      -> "Tony Menzo",
  Version      -> "1.0.0",
  Date         -> "11.11.2025",
  Institutions -> {"University of Alabama", "Fermilab"},
  Emails       -> "amenzo@ua.edu"
};

M$InteractionOrderHierarchy = {
  {NP, 2}
};

(******************************************)
(******************************************)
(*               Parameters               *)
(******************************************)
(******************************************)


M$Parameters = {

  (* S1 leptoquark mass *)
  (*MS1 == {
      ParameterType -> External,
      BlockName     -> BSMINPUTS,
      Value         -> 1500.0,
      Description   -> "S1 mass"
  },*)

  (* Real Yukawa for S1 -> e u *)
  yRR11 == {
      ParameterType -> External,
      Blockname -> BSMINPUTS, 
      ComplexParameter -> False,
      InteractionOrder -> {NP, 1},
      Value -> 0.5,
      Description -> "S1-e-u Yukawa"
    }
};

(******************************************)
(******************************************)
(*            Field Definitions           *)
(******************************************)
(******************************************)

M$ClassesDescription = {

(******************************************)
(* Scalar singlet S1^\dagger = (3,1,-1/3) *)
(******************************************)

S[100] == {
    ClassName        -> S1,
    Mass             -> {MS1, 1500.},
    Width            -> {W1, Automatic},
    SelfConjugate    -> False,
    PropagatorLabel  -> "S1",
    PropagatorType   -> ScalarDash,
    PropagatorArrow  -> None,
    QuantumNumbers   -> {Q -> -1/3},
    Indices          -> {Index[Colour]},
    ParticleName     -> "S1",
    AntiParticleName -> "S1~",
    FullName         -> "Scalar leptoquark S1"
}

};

(******************************************)
(******************************************)
(*              Lagrangians               *)
(******************************************)
(******************************************)

(* Kinetic + mass terms (use SM gauge groups already loaded). *)
LkinS1 = Block[{mu,aa},
  ExpandIndices[
    (*HC[DC[S1, mu]] . DC[S1, mu]*) 
    DC[S1bar[aa],mu] DC[S1[aa],mu] - MS1^2 * HC[S1].S1
    ]
];

(* Yukawa coupling to e u (first generation). *)
L1YukRRNonHC := Block[{sp, aa},
  yRR11 * anti[CC[uR]][sp, 1, aa].lR[sp, 1] * HC[S1][aa]
];

(* Add Hermitian conjugate. *)
L1YukRR := L1YukRRNonHC + HC[L1YukRRNonHC];

(* Full BSM Lagrangian. *)
LBSM = LkinS1 + L1YukRR;

    return _quote(v)


def _pdg(v) -> str:
    if isinstance(v, list):
        return "{" + ", ".join(str(x) for x in v) + "}"
    return str(v)


def _indices(names: Sequence[str]) -> str:
    return "{" + ", ".join(f"Index[{n}]" for n in names) + "}"


# FeynRules QuantumNumbers holds only additive (U(1)-type) charges. Colour/SU2/
# etc. are REPRESENTATION labels fixed by a field's Indices, not quantum numbers;
# if left in QuantumNumbers, FeynRules emits an unevaluated `Colour[field]` into
# the UFO's particles.py, which MadGraph rejects with "name 'Colour' is not
# defined". Drop these reserved index/representation names.
_REP_LABELS = {
    "Colour", "Color", "Sextet", "Gluon", "Generation", "Spin", "Lorentz",
    "SU2", "SU2W", "SU2L", "SU2D", "SU2R",
}


def _additive_qns(d: dict) -> dict:
    return {k: v for k, v in d.items() if k not in _REP_LABELS}


def _reserved_mass_width_names(particles) -> set:
    """Mass/width parameter names FeynRules auto-declares from particle Mass/Width
    specs. Declaring them again in M$Parameters double-defines the name in the UFO
    (MadGraph InvalidModel), so the renderer drops those duplicates."""
    names: set = set()
    for p in particles or []:
        for spec in (getattr(p, "mass", None), getattr(p, "width", None)):
            if spec is None:
                continue
            if getattr(spec, "sym", None):
                names.add(spec.sym)
            for sub, _val in (getattr(spec, "members", None) or []):
                names.add(sub)
    return names


